  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Lopinavir, which shares the hydroxyethylene core with two benzyl groups and a valine amide with the query, has low oral bioavailability due to extensive CYP3A4 first-pass metabolism and P-gp efflux.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Enalkiren, a peptidomimetic renin inhibitor with a similar peptide-like backbone and aromatic side chains, has a human oral bioavailability of only 0.5%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "SRT2104, a thiazole-containing small molecule, has an absolute oral bioavailability of 13.8% (range 2–27%) in the fasted state in humans, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "GHRP-6, a peptide with multiple amide bonds, has a systemic availability of ~0.3% after oral administration in humans, supporting low oral bioavailability for peptide-like molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a peptidomimetic with a hydroxyethylene core and valine amide, closely resembling lopinavir, which has low oral bioavailability. Additional peptidomimetic and thiazole-containing analogues (enalkiren 0.5%, SRT2104 13.8% fasted) all fall below the 20% threshold. No evidence supports high bioavailability, so the prediction is low.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability value is available for the query molecule itself.",
    "Lopinavir's low bioavailability is reported qualitatively rather than as a numeric F value, though it is consistently described as low/poor.",
    "The most structurally similar analogue (lopinavir) is not measured under the same fasted-state absolute bioavailability protocol as the query condition."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
